                    if ($quote -eq "'") {
                        if ($next -eq "'" -or $next -eq '\') {
                            [void]$sb.Append($next)
                        } else {
                            [void]$sb.Append('\')
                            [void]$sb.Append($next)
                        }
                    } else {
                        switch ([string]$next) {
                            'n' { [void]$sb.Append("`n") }
                            'r' { [void]$sb.Append("`r") }
                            't' { [void]$sb.Append("`t") }
                            '\' { [void]$sb.Append('\') }
                            '"' { [void]$sb.Append('"') }
                            '$' { [void]$sb.Append('$') }
