                $curr = $stack.Pop()
                if ($null -eq $curr -or $curr -is [string] -or $curr -is [ValueType] -or $curr -is [AllPhp.ByteValues.PhpBytes]) { continue }
                if ($curr -is [System.Collections.IList]) {
                    foreach ($item in $curr) { $stack.Push($item) }
