                    if ($k -ceq 'yield' -or $k -ceq 'yield_from') { return $true }
                    if ($k -in @('functiondef','closure','classdef','traitdef','interfacedef','enumdef')) { continue }
                }
                foreach ($prop in $curr.PSObject.Properties) {
