                    $b = Invoke-PhpExpr $node.Right
                    switch ($node.Op) {
                        '**' { $nums = Convert-PhpBinaryNumericOperands $a $b '**'; return (Php-Pow $nums[0] $nums[1]) }
                        '.' { return (To-PhpBytes $a).Concat((To-PhpBytes $b)) }
                        '+' {
                            if ((Is-PhpArray $a) -and (Is-PhpArray $b)) {
